// A stand-in written for this fixture, not the published bytes of @solidjs/web@2.0.0-rc.21 `frames/dist/client.js`: `createFrame` morphs the existing children of the
// boundary with the attributes of the server's markup, `type` included, as `frames/dist/wire.js` `morphAttributes` does (lines 73-97: `oldEl.setAttribute(name, attr.value)`).
// The published morph tier is loaded lazily and takes the names from the markup; this stand-in writes the one attribute the fixture is about, by a literal name.
export function createFrame(boundary, server) {
  for (const oldEl of boundary.children) {
    if (server) oldEl.setAttribute("type", server.getAttribute("type") ?? "");
  }
}
